ideas_db = {}

@app.route("/idea", methods=["POST"])
def create_idea():
    idea = request.form.get("idea")
    description = request.form.get("description")
    if not idea or not description:
        return jsonify({"error": "Idea and description are required"}), 400

    idea_id = len(ideas_db) + 1
    ideas_db[idea_id] = {"idea": idea, "description": description}
    return jsonify({"id": idea_id, "idea": idea, "description": description}), 201

@app.route("/idea/<int:idea_id>", methods=["GET"])
def get_idea(idea_id):
    idea = ideas_db.get(idea_id)
    if not idea:
        return jsonify({"error": "Idea not found"}), 404
    return jsonify(idea)

@app.route("/idea/<int:idea_id>", methods=["PUT"])
def update_idea(idea_id):
    idea = request.form.get("idea")
    description = request.form.get("description")
    if not idea and not description:
        return jsonify({"error": "Idea or description is required"}), 400

    if idea_id not in ideas_db:
        return jsonify({"error": "Idea not found"}), 404

    ideas_db[idea_id]["idea"] = idea
    ideas_db[idea_id]["description"] = description
    return jsonify({"id": idea_id, "idea": idea, "description": description})

@app.route("/idea/<int:idea_id>", methods=["DELETE"])
def delete_idea(idea_id):
    if idea_id not in ideas_db:
        return jsonify({"error": "Idea not found"}), 404

    del ideas_db[idea_id]
    return jsonify({"message": "Idea deleted successfully"})
