import os
import shutil

class Artifact:
    def __init__(self, name, file_path):
        self.name = name
        self.file_path = file_path

    def validate(self):
        if not os.path.exists(self.file_path):
            raise FileNotFoundError(f"Artifact {self.name} not found at {self.file_path}")

    def distribute(self, destination):
        self.validate()
        destination_path = os.path.join(destination, self.name)
        shutil.copy(self.file_path, destination_path)
        print(f"Distributed artifact {self.name} to {destination_path}")

class Pipeline:
    def __init__(self, name, steps):
        self.name = name
        self.steps = steps

    def run(self, artifacts):
        for step in self.steps:
            if callable(step):
                step(artifacts)
            else:
                print(f"Step {step} is not callable")

    @staticmethod
    def create_artifact(name, file_path):
        return Artifact(name, file_path)

class Distribution:
    def __init__(self, method, target):
        self.method = method
        self.target = target

    def distribute(self, artifacts):
        for artifact in artifacts:
            artifact.distribute(self.target)

# Example usage
if __name__ == "__main__":
    # Create artifacts
    artifact1 = Pipeline.create_artifact("artifact1", "path/to/artifact1.tar.gz")
    artifact2 = Pipeline.create_artifact("artifact2", "path/to/artifact2.tar.gz")

    # Define pipeline steps
    def step1(artifacts):
        print("Running Step 1")
        # Example step: rename artifact
        artifacts[0].file_path = "renamed/" + artifacts[0].file_path

    def step2(artifacts):
        print("Running Step 2")
        # Example step: copy artifact to another location
        shutil.copy(artifacts[1].file_path, "path/to/copy/artifact2.tar.gz")

    # Create pipeline
    pipeline = Pipeline("example-pipeline", [step1, step2])

    # Run pipeline
    pipeline.run([artifact1, artifact2])

    # Distribute artifacts
    distribution = Distribution(method="scp", target="user@remote_host:/path/to/distribution")
    distribution.distribute([artifact1, artifact2])
```

### Explanation:
1. **Artifact Class**: Represents an artifact with a name and a file path. It includes methods for validating the existence of the artifact and distributing it to a specified destination.
2. **Pipeline Class**: Manages a sequence of steps that can be executed on artifacts. It includes a method for running the pipeline and a static method for creating artifacts.
3. **Distribution Class**: Handles the distribution of artifacts using a specified method and target location. It includes a method for distributing artifacts.

This example provides a basic framework that you can expand upon based on your specific requirements. Each class has clear responsibilities, making the code modular and easier to maintain.

