import re
from datetime import datetime

class LogParser:
    def __init__(self, log_file_path):
        self.log_file_path = log_file_path
        self.ip_address_count = {}
        self.user_agent_dict = {}

    def parse_log(self):
        with open(self.log_file_path, 'r') as file:
            for line in file:
                self.process_line(line)

    def process_line(self, line):
        # Use regular expression to extract necessary information from the log line
        match = re.match(r'(\S+) (\S+) (\S+) \[([\w:/]+\s[+\-]\d{4})\] "([^"]+)" (\d{3}|-) (\d+)', line)
        if match:
            ip_address, _, user_agent, timestamp, _, _, _ = match.groups()

            # Count requests per IP address
            if ip_address in self.ip_address_count:
                self.ip_address_count[ip_address] += 1
            else:
                self.ip_address_count[ip_address] = 1

            # Aggregate user agents
            if user_agent in self.user_agent_dict:
                self.user_agent_dict[user_agent] += 1
            else:
                self.user_agent_dict[user_agent] = 1

    def generate_report(self):
        print("IP Address Traffic Report:")
        for ip, count in self.ip_address_count.items():
            print(f"{ip}: {count}")

        print("\nUser Agent Breakdown:")
        for user_agent, count in sorted(self.user_agent_dict.items(), key=lambda item: item[1], reverse=True):
            print(f"{user_agent}: {count}")

