import csv

def anonymize(row):
    anonymized_data = []
    reader = csv.reader([row])
    header = next(reader)

    for cell_index, cell_value in enumerate(header):
        if cell_value.lower() == 'employee_id' or cell_value.lower() == 'social_security_number':
